    deep_before_after_html: '<div class="deep-grid-3"><div class="deep-card"><h3>Distortion Correction</h3><p style="color:var(--steel-2);font-size:12px;margin-bottom:12px">Before / After</p><div style="background:var(--ink-0);height:120px;display:flex;align-items:center;justify-content:center;color:var(--steel-1);font-family:var(--ff-mono);font-size:10px">POST-WELD STRAIGHTENING</div></div><div class="deep-card"><h3>Surface Treatment</h3><p style="color:var(--steel-2);font-size:12px;margin-bottom:12px">Before Blasting / Sa 2½</p><div style="background:var(--ink-0);height:120px;display:flex;align-items:center;justify-content:center;color:var(--steel-1);font-family:var(--ff-mono);font-size:10px">BLASTING BEFORE / AFTER</div></div><div class="deep-card"><h3>NDT Repair</h3><p style="color:var(--steel-2);font-size:12px;margin-bottom:12px">UT Reject / Post-Repair Approval</p><div style="background:var(--ink-0);height:120px;display:flex;align-items:center;justify-content:center;color:var(--steel-1);font-family:var(--ff-mono);font-size:10px">NDT DEFECT / REPAIR</div></div></div>',
