      "services_saw_num": "// NEW · SUBMERGED ARC WELDING",
      "services_saw_h2": "35 m Submerged<br/>Arc Welding Line.",
      "services_saw_desc": "Our new 35-metre submerged arc welding machine welds long linear seams, machinery and crane booms, and trailer and machine chassis in one set-up, at constant parameters and to a qualified WPS.",
      "services_saw_f1": "Long linear seams: girders, box sections, plates and tank shells",
      "services_saw_f2": "Boom welding: construction machinery, crane and platform booms",
      "services_saw_f3": "Chassis welding: trailers, agricultural and construction machinery",
      "services_saw_f4": "EN ISO 3834-2 quality framework, parameter records and NDT",
      "services_saw_btn": "Submerged Arc Welding Service",
      "home_saw_eyebrow": "New equipment",
      "home_saw_h2": "Our 35 m submerged arc welder <span style=\"color:var(--arc-2)\">is now in production.</span>",
      "home_saw_p": "Submerged arc welding for long linear seams, booms and chassis, in one set-up with repeatable quality.",
