      "cut_r4k": "Materials",
      "cut_r5k": "Material certificate",
      "cut_r5v": "EN 10204 3.1 · heat number matched to the part list",
      "cut_r6k": "Quotation",
      "cut_r6v": "48 hours · one price, one lead time · NDA standard",
      "cut_s3_label": "Process",
      "cut_s3_title": "How We Work",
      "cut_st1_h": "Drawing and Cutting Plan",
      "cut_st1_p": "Your DXF/STEP file is reviewed for manufacturability; cutting plan, bending sequence and weld preparation are prepared by ArmaWeld.",
      "cut_st2_h": "Material and Cutting",
      "cut_st2_p": "Plate is sourced with 3.1 certificates; laser or plasma cutting is done at a partner facility to ArmaWeld's cutting plan.",
      "cut_st3_h": "Bending and Incoming Inspection",
      "cut_st3_p": "Bent parts arrive at ArmaWeld; angle, dimension and surface are checked, and non-conforming parts never reach welding.",
      "cut_st4_h": "Welding, Inspection and Delivery",
      "cut_st4_p": "Welding to approved WPS, NDT and dimensional report; painting and assembly if required. The part is delivered assembly-ready with its document file.",
      "cut_s4_label": "Typical Parts",
      "cut_s4_title": "Which Parts Is This For?",
      "cut_s4_desc": "For any part that needs welding after cutting and bending; cutting-only or bending-only orders can also be quoted.",
      "cut_sec1_h": "Brackets and Consoles",
      "cut_sec1_p": "Bent brackets, connection plates",
