      "cut_l_chassis": "Chassis and boom fabrication",
      "cut_l_blog1": "Laser and plasma cutting guide",
      "cut_l_blog2": "Sheet metal bending tolerances",
      "cut_cta_h": "Send your DXF, receive assembly-ready parts",
